 if key=="pools"{let opts=array(st,"profiles").iter().enumerate().map(|(i,p)|obj(vec![("label",s(&format!("{} · {}",text(p,"name"),text(p,"model")))),("value",s(&i.to_string()))])).collect();let mut c=field_ui("connection","Model connection",&scalar(&e,"connection"),"choice");put(&mut c,"options",Arr(opts));f.push(c);f.push(choice("role","Allowed role",&text(&e,"role"),&[("Any role","any"),("Orchestrator","orchestrator"),("Coding","coding"),("Non-writing auditor/tester","nonwrite")]));f.push(field_ui("count","Maximum live/suspended agents using this model and role (1–64)",&scalar(&e,"count"),"number"));f.push(field_ui("note","Current scheduler","The existing recursive scheduler runs one request at a time. These counts are limits, not a claim of parallel execution. Roles/specialties belong to agent profiles; this list chooses models and slot ceilings.","readonly"));}
