 if a=="harness_memory_accept"||a=="harness_memory_decline"{let record=get(st,"harness_memory_pending").clone();if record==Null||get(&record,"binding")!=&conflict_binding(st){return Err("This memory observation is stale; no memory was changed".into());}let mut next=st.clone();if a=="harness_memory_accept"{version(st,false)?;let mut p=policy(st);if p==Null{p=obj(vec![]);}put(&mut p,"schema",Num("1".into()));let mut list=array(&p,"memory");if list.len()>=MAX_ROWS{return Err("Memory contains64 records; reuse or archive an existing item".into());}let mut saved=record;if let Obj(m)=&mut saved{m.remove("binding");}put(&mut saved,"user_reviewed",Bool(true));list.push(saved);put(&mut p,"memory",Arr(list));admission(st,&p)?;put(&mut next,"harness_policy",p);}put(&mut next,"harness_memory_pending",Null);put(&mut next,"dialog",s("harness_settings"));put(&mut next,"notice",s(if a=="harness_memory_accept"{"Reviewed memory observation saved; harness rules are unchanged."}else{"Memory observation declined; nothing saved; harness rules unchanged."}));if get(st,"task_run")!=&Null{continue_instruction(&mut next,if a=="harness_memory_accept"{"The user reviewed and saved the fallible memory observation. Continue the original task; memory is lower authority than harness/project rules."}else{"The user declined the memory observation. Nothing was saved; continue the original task."})?;let index=number(st,"request_index");let effect=model_effect_at(&mut next,index)?;*st=next;return Ok(effect);}*st=next;return Ok(Null);}
 if a=="harness_memory_review"{if get(st,"harness_memory_pending")==&Null{return Err("No memory observation awaits review".into());}put(st,"dialog",s(a));return Ok(Null);}
 if a=="harness_settings"{put(st,"dialog",s(a));return Ok(Null);}
 if a=="harness_project"{clear_form(st);put(st,"dialog",s(a));return Ok(Null);}
 let mut p=policy(st);if p==Null{p=obj(vec![]);}else if !matches!(&p,Obj(_)){p=obj(vec![("preserve_raw",p)]);}put(&mut p,"schema",Num("1".into()));
 if a=="harness_project_save"{let value=text(inputs,"project_text");if value.len()>65536{return Err("Project instructions exceed64KiB".into());}let mut records=array(&p,"projects");let root=get(st,"approval_root").clone();let identity=get(st,"approval_root_identity").clone();let record=obj(vec![("root",root.clone()),("identity",identity.clone()),("text",s(&value))]);if let Some(i)=records.iter().position(|r|get(r,"root")==&root&&get(r,"identity")==&identity){records[i]=record;}else{if records.len()>=MAX_ROWS{return Err("Project records are full".into());}records.push(record);}put(&mut p,"projects",Arr(records));admission(st,&p)?;put(st,"harness_policy",p);clear_form(st);refresh(st);put(st,"notice",s("Project instructions saved for this workspace identity"));return Ok(Null);}
 if let Some(key)=a.strip_prefix("harness_"){if ["rules","decisions","pools","memory"].contains(&key){clear_form(st);put(st,"harness_section",s(key));put(st,"dialog",s("harness_list"));return Ok(Null);}}
 if a=="harness_list"{put(st,"dialog",s(a));return Ok(Null);}
 let key=section(st);if !["rules","decisions","pools","memory"].contains(&key.as_str()){return Err("Open a harness section first".into());}let mut list=array(&p,&key);
 if a=="harness_item_new"{clear_form(st);put(st,"harness_edit",obj(vec![("id",s(&id()?)),("text",s("")),("scope",s("all")),("decision",s(if key=="rules"{"context"}else{"ask"})),("role",s("any")),("count",Num("1".into())),("connection",Num("0".into())),("origin",s("User-entered exact text")),("enabled",Bool(true))]));put(st,"harness_index",Num(list.len().to_string()));put(st,"dialog",s("harness_item"));return Ok(Null);}
 if let Some(index)=a.strip_prefix("harness_item:"){let i=index.parse::<usize>().map_err(|_|"Invalid harness item")?;let r=list.get(i).cloned().ok_or("Harness item unavailable")?;clear_form(st);put(st,"harness_edit",r);put(st,"harness_index",Num(i.to_string()));put(st,"dialog",s("harness_item"));return Ok(Null);}
